  1	'use client';
  2	import { useEffect, useRef, useState, type FormEvent, type KeyboardEvent } from 'react';
  3	import { RECOMMEND, decisionOf, type Answer } from '@/lib/interview';
  4	import type { State, TurnView } from '@/lib/session';
  5	import { Agent, Alert, Check, Clock, Undo } from '../../icons';
  6	
  7	type Busy = null | 'answer' | 'wrap' | 'more' | 'back' | 'finish';
  8	
  9	export default function Interview({ initial }: { initial: State }) {
 10	  const [state, setState] = useState(initial);
 11	  const [busy, setBusy] = useState<Busy>(null);
 12	  const [pending, setPending] = useState<Answer | null>(null);
 13	  const [error, setError] = useState('');
 14	  const [moved, setMoved] = useState(false); // animate the card only after a step change, never on page load
 15	
 16	  async function send(action: Exclude<Busy, null>, extra: Record<string, unknown> = {}) {
 17	    setBusy(action);
 18	    setError('');
 19	    setMoved(true);
 20	    try {
 21	      const res = await fetch(`/api/sessions/${state.id}`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ action, ...extra }) });
 22	      const data = await res.json().catch(() => ({ error: '서버 응답을 읽지 못했어요.' }));
 23	      if (!res.ok) throw new Error(data.error ?? '처리하지 못했어요.');
 24	      setState(data as State);
 25	      if (action === 'finish') window.scrollTo({ top: 0 });
 26	    } catch (e) {
 27	      setError((e as Error).message || '연결이 끊겼어요. 다시 시도해 주세요.');
 28	    } finally {
 29	      setBusy(null);
 30	      setPending(null);
 31	    }
 32	  }
 33	
 34	  if (state.status === 'done' && state.result) return <Result state={state} />;
 35	
 36	  const answered = state.turns.filter((t) => t.answer || (pending && t.id === state.open?.id)).map((t) => (t.answer ? t : { ...t, answer: pending }));
 37	  const waiting = busy === 'answer' || busy === 'more';
 38	  const asked = state.turns.length;
 39	
 40	  return (
 41	    <div className="layout">
 42	      <div className="layout__main">
 43	        <div className="page-head">
 44	          <div className="page-head__text">
 45	            <h1 className="prompt-title">{state.prompt}</h1>
 46	            <p className="page-head__desc">질문에 답할수록 오른쪽의 애매한 부분이 줄어들어요. 최대 {state.maxQuestions}개까지 물어봐요.</p>
 47	          </div>
 48	        </div>
 49	
 50	        <ol className="flow" aria-label="질문 워크플로우">
 51	          {answered.map((t) => <Step key={t.id} turn={t} />)}
 52	          <li className="flow__step flow__step--current">
 53	            <span className="flow__node num" aria-hidden="true">{waiting ? asked + 1 : state.open ? state.open.idx + 1 : <Check />}</span>
 54	            <div className="flow__body">
 55	              {waiting ? (
 56	                <Loading label={busy === 'answer' ? '다음 질문을 만드는 중이에요.' : '질문을 하나 더 만드는 중이에요.'} />
 57	              ) : state.open ? (
 58	                <QuestionCard
 59	                  key={state.open.id} turn={state.open} max={state.maxQuestions} enter={moved} busy={busy} error={error}
 60	                  onAnswer={(a) => { setPending(a); send('answer', { turnId: state.open!.id, ...a }); }}
 61	                  onBack={() => send('back')} onWrap={() => send('wrap')}
 62	                />
 63	              ) : state.restate ? (
 64	                <Restate restate={state.restate} enter={moved} busy={busy} error={error} onFinish={() => send('finish')} onMore={() => send('more')} onBack={() => send('back')} />
 65	              ) : (
 66	                <div className="notice notice--error" role="alert"><Alert /><p>다음 단계를 불러오지 못했어요. 새로 고쳐 주세요.</p></div>
 67	              )}
 68	            </div>
 69	          </li>
 70	        </ol>
 71	      </div>
 72	      <Ledger state={state} current={waiting ? null : state.open?.track ?? null} />
 73	    </div>
 74	  );
 75	}
 76	
 77	function Step({ turn }: { turn: TurnView }) {
 78	  return (
 79	    <li className="flow__step">
 80	      <span className="flow__node num" aria-hidden="true">{turn.idx + 1}</span>
 81	      <div className="flow__body">
 82	        <ol className="chat">
 83	          <li className="msg msg--agent">
 84	            <p className="msg__who"><Agent />질문 {turn.idx + 1}<span className="flow__track">{turn.trackLabel}</span></p>
 85	            <div className="msg__body"><p>{turn.question}</p></div>
 86	          </li>
 87	          <li className="msg msg--user">
 88	            <p className="msg__who visually-hidden">내 답</p>
 89	            <div className="msg__body"><p>{decisionOf(turn)}</p></div>
 90	          </li>
 91	        </ol>
 92	      </div>
 93	    </li>
 94	  );
 95	}
 96	
 97	function Loading({ label }: { label: string }) {
 98	  return (
 99	    <section className="panel qcard" aria-busy="true" aria-label={label}>
100	      <div className="panel__body qcard__body">
101	        <p className="meta" role="status">{label} LLM을 쓰면 30초쯤 걸려요.</p>
102	        <span className="skeleton" style={{ width: '80%' }} />
103	        <span className="skeleton" style={{ width: '55%' }} />
104	        <span className="skeleton qcard__skel-chip" style={{ width: '45%' }} />
105	        <span className="skeleton qcard__skel-chip" style={{ width: '50%' }} />
106	        <span className="skeleton qcard__skel-chip" style={{ width: '40%' }} />
107	      </div>
108	    </section>
109	  );
110	}
111	
112	function ErrorNotice({ error }: { error: string }) {
113	  return error ? <div className="notice notice--error" role="alert"><Alert /><p>{error}</p></div> : null;
114	}
115	
116	function QuestionCard({ turn, max, enter, busy, error, onAnswer, onBack, onWrap }: {
117	  turn: TurnView; max: number; enter: boolean; busy: Busy; error: string;
118	  onAnswer: (a: Answer) => void; onBack: () => void; onWrap: () => void;
119	}) {
120	  const [choices, setChoices] = useState<string[]>([]);
121	  const [text, setText] = useState('');
122	  const [empty, setEmpty] = useState(false);
123	  const heading = useRef<HTMLHeadingElement>(null);
124	  const all = [...turn.options, RECOMMEND];
125	  const locked = busy !== null;
126	
127	  // Move focus to each new question (not on first page load) so keyboard and screen-reader users land on it.
128	  useEffect(() => {
129	    if (!enter) return;
130	    heading.current?.focus({ preventScroll: true });
131	    heading.current?.scrollIntoView({ block: 'nearest' });
132	  }, [turn.idx, enter]);
133	
134	  function toggle(o: string) {
135	    setEmpty(false);
136	    if (!turn.multi) return setChoices([o]);
137	    setChoices((c) => (c.includes(o) ? c.filter((x) => x !== o) : o === RECOMMEND ? [o] : [...c.filter((x) => x !== RECOMMEND), o]));
138	  }
139	
140	  function submit(e?: FormEvent) {
141	    e?.preventDefault();
142	    if (locked) return;
143	    if (!choices.length && !text.trim()) return setEmpty(true);
144	    onAnswer({ choices, text: text.trim() });
145	  }
146	
147	  function keys(e: KeyboardEvent<HTMLFormElement>) {
148	    if ((e.target as HTMLElement).tagName === 'TEXTAREA' || e.metaKey || e.ctrlKey || e.altKey) return;
149	    const n = Number(e.key);
150	    if (n >= 1 && n <= all.length) { e.preventDefault(); toggle(all[n - 1]); }
151	  }
152	
153	  const fallback = turn.provider.startsWith('mock (');
154	  return (
155	    <section className={`panel qcard${enter ? ' qcard--enter' : ''}`} aria-labelledby={`q-${turn.id}`}>
156	      <form onSubmit={submit} onKeyDown={keys} noValidate>
157	        <div className="panel__body qcard__body">
158	          <p className="meta num">질문 {turn.idx + 1} / {max}<span className="flow__track">{turn.trackLabel}</span></p>
159	          <h2 className="qcard__q" id={`q-${turn.id}`} ref={heading} tabIndex={-1}>{turn.question}</h2>
160	          {turn.hint && <p className="qcard__hint">{turn.hint}</p>}
161	          <fieldset className="choices choices--stack" disabled={locked} aria-describedby={empty ? `e-${turn.id}` : undefined}>
162	            <legend>{turn.multi ? '여러 개 골라도 돼요' : '하나만 골라 주세요'}</legend>
163	            {all.map((o, i) => (
164	              <label className={`chip${o === RECOMMEND ? ' chip--recommend' : ''}`} key={o}>
165	                <input type={turn.multi ? 'checkbox' : 'radio'} name={`choice-${turn.id}`} value={o} checked={choices.includes(o)} onChange={() => toggle(o)} />
166	                <Check className="chip__check" />
167	                <span className="chip__key num" aria-hidden="true">{i + 1}</span>
168	                {o}
169	              </label>
170	            ))}
171	          </fieldset>
172	          {turn.allowFree && (
173	            <div className="field">
174	              <label className="field__label" htmlFor={`t-${turn.id}`}>직접 쓰기</label>
175	              <textarea
176	                className="textarea qcard__text" id={`t-${turn.id}`} rows={2} maxLength={500} disabled={locked}
177	                placeholder="예: 둘 다 좋은데, 밤에는 분위기가 바뀌었으면 해요" value={text}
178	                onChange={(e) => { setText(e.target.value); setEmpty(false); }}
179	                onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); submit(); } }}
180	                aria-describedby={`h-${turn.id}${empty ? ` e-${turn.id}` : ''}`} aria-invalid={empty || undefined}
181	              />
182	              <p className="field__help" id={`h-${turn.id}`}>보기와 함께 써도 돼요. Enter로 보내고 Shift+Enter로 줄을 바꿔요. 숫자 키로 보기를 고를 수 있어요.</p>
183	            </div>
184	          )}
185	          {empty && <p className="field__error" id={`e-${turn.id}`}>보기를 고르거나 직접 써 주세요.</p>}
186	          {fallback && <p className="meta">{turn.provider}로 만든 질문이에요.</p>}
187	          <ErrorNotice error={error} />
188	        </div>
189	        <footer className="panel__foot btn-row">
190	          <button type="submit" className="btn btn--primary" disabled={locked} aria-busy={busy === 'answer'}>다음 질문</button>
191	          {turn.idx > 0 && <button type="button" className="btn btn--ghost" onClick={onBack} disabled={locked} aria-busy={busy === 'back'}><Undo />이전</button>}
192	          {turn.idx > 0 && <button type="button" className="btn btn--ghost qcard__wrap" onClick={onWrap} disabled={locked} aria-busy={busy === 'wrap'}>여기까지로 정리하기</button>}
193	        </footer>
194	      </form>
195	    </section>
196	  );
197	}
198	
199	function Restate({ restate, enter, busy, error, onFinish, onMore, onBack }: {
200	  restate: NonNullable<State['restate']>; enter: boolean; busy: Busy; error: string; onFinish: () => void; onMore: () => void; onBack: () => void;
201	}) {
202	  const heading = useRef<HTMLHeadingElement>(null);
203	  useEffect(() => { if (enter) heading.current?.focus({ preventScroll: true }); }, [enter]);
204	  const locked = busy !== null;
205	  return (
206	    <section className={`panel qcard${enter ? ' qcard--enter' : ''}`} aria-labelledby="restate-h" aria-busy={busy === 'finish'}>
207	      <div className="panel__body qcard__body">
208	        <h2 className="qcard__q" id="restate-h" ref={heading} tabIndex={-1}>이대로 정리할까요?</h2>
209	        <p className="qcard__goal">{restate.goal}</p>
210	        <dl className="decisions">
211	          {restate.decisions.map((d) => (
212	            <div key={d.track}><dt>{d.track}</dt><dd>{d.decision}</dd></div>
213	          ))}
214	        </dl>
215	        {restate.fuzzy.length > 0 && <p className="meta">아직 정하지 않은 것: {restate.fuzzy.join(', ')}</p>}
216	        {busy === 'finish' && <div className="notice" role="status"><Clock /><p>게임 이름과 설명을 정리하는 중이에요. LLM을 쓰면 30초쯤 걸려요.</p></div>}
217	        <ErrorNotice error={error} />
218	      </div>
219	      <footer className="panel__foot btn-row">
220	        <button type="button" className="btn btn--primary" onClick={onFinish} disabled={locked} aria-busy={busy === 'finish'}>이대로 정리하기</button>
221	        {restate.canAskMore && <button type="button" className="btn" onClick={onMore} disabled={locked}>질문 하나 더</button>}
222	        <button type="button" className="btn btn--ghost" onClick={onBack} disabled={locked} aria-busy={busy === 'back'}><Undo />이전</button>
223	      </footer>
224	    </section>
225	  );
226	}
227	
228	function Ledger({ state, current }: { state: State; current: string | null }) {
229	  return (
230	    <aside className="panel layout__side ledger" aria-labelledby="ledger-h">
231	      <header className="panel__head"><h2 className="panel__title" id="ledger-h">애매한 부분</h2></header>
232	      <div className="panel__body">
233	        <p className="ledger__total">
234	          <span className="ledger__num num">{state.overall.toFixed(2)}</span>
235	          <span className="meta">전체 애매함이에요. 0.20 이하가 되면 정리해요.</span>
236	        </p>
237	        <ul className="ledger__list">
238	          {state.ledger.map((l) => (
239	            <li className="ledger__row" key={l.key} data-clear={l.clear} aria-current={l.key === current ? 'step' : undefined}>
240	              <span className="ledger__label">{l.label}{l.key === current && <span className="visually-hidden">, 지금 묻는 중</span>}</span>
241	              <span className="ledger__state">{l.clear ? <><Check />명확</> : '애매'}</span>
242	              <span className="ledger__bar" aria-hidden="true"><span style={{ transform: `scaleX(${l.score})` }} /></span>
243	              <span className="ledger__score num">{l.score.toFixed(2)}</span>
244	            </li>
245	          ))}
246	        </ul>
247	        <p className="meta">0은 정해졌다는 뜻, 1은 아직 모른다는 뜻이에요.</p>
248	      </div>
249	    </aside>
250	  );
251	}
252	
253	function Result({ state }: { state: State }) {
254	  const r = state.result!;
255	  const c = r.concept;
256	  return (
257	    <div className="layout">
258	      <div className="layout__main result">
259	        <div className="result__head">
260	          <h1 className="result__title">{r.title}<span className="result__tag">가제</span></h1>
261	          <p className="result__one">{r.one_liner}</p>
262	          <div className="btn-row">
263	            <a className="btn btn--primary" href={`http://localhost:3102/?from=step1:${state.id}`}>워크플로우로 열기</a>
264	            <a className="btn" href="/">새로 시작</a>
265	          </div>
266	        </div>
267	        <article className="md-doc">
268	          <h2>이게 뭐냐면</h2>
269	          <p>{c.what}</p>
270	          <h2>비유하자면</h2>
271	          <p>{c.analogy}</p>
272	          <h2>조금 더 자세히</h2>
273	          <ul>{c.details.map((d) => <li key={d}>{d}</li>)}</ul>
274	          <h2>그래서 왜 재밌냐면</h2>
275	          <p>{c.so_what}</p>
276	          <h2>결정한 것들</h2>
277	          <table>
278	            <thead><tr><th scope="col">항목</th><th scope="col">결정</th></tr></thead>
279	            <tbody>{c.decisions.map((d) => <tr key={d.track}><th scope="row">{d.track}</th><td>{d.decision}</td></tr>)}</tbody>
280	          </table>
281	          <h2>질문 워크플로우</h2>
282	          <p className="meta">처음 아이디어: {state.prompt}</p>
283	        </article>
284	        <ol className="flow flow--result" aria-label="질문 워크플로우">
285	          {state.turns.filter((t) => t.answer).map((t) => <Step key={t.id} turn={t} />)}
286	        </ol>
287	        <p className="meta">정리한 모델: {r.provider}</p>
288	      </div>
289	      <Ledger state={state} current={null} />
290	    </div>
291	  );
292	}

