1	// Ouroboros-style Socratic interview for a vibe game prompt: ambiguity tracks, breadth control, stop rule, ELI5 wording.
2	// Pure functions only (no db/llm imports) so lib/interview.test.mjs runs under plain `node --test`.
3	
4	export type TrackKey = 'fun' | 'role' | 'loop' | 'win' | 'platform' | 'mood' | 'audience' | 'unique';
5	export type Ledger = Record<TrackKey, number>;
6	export type Answer = { choices: string[]; text: string };
7	export type Turn = { track: TrackKey; question: string; options: string[]; answer: Answer | null };
8	export type Question = { track: TrackKey; question: string; hint: string; options: string[]; multi: boolean; allow_free: boolean };
9	export type Concept = { title: string; one_liner: string; what: string; analogy: string; details: string[]; so_what: string };
10	export type Decision = { key: TrackKey; track: string; decision: string };
11	
12	export const TRACKS: { key: TrackKey; label: string; weight: number }[] = [
13	  { key: 'fun', label: '핵심 재미', weight: 0.18 },
14	  { key: 'role', label: '플레이어 역할', weight: 0.12 },
15	  { key: 'loop', label: '코어 루프', weight: 0.18 },
16	  { key: 'win', label: '이기고 지는 조건', weight: 0.14 },
17	  { key: 'platform', label: '플랫폼과 한 판 길이', weight: 0.08 },
18	  { key: 'mood', label: '분위기와 그림체', weight: 0.09 },
19	  { key: 'audience', label: '누가 할 게임인지', weight: 0.09 },
20	  { key: 'unique', label: '다른 게임과 다른 점', weight: 0.12 },
21	];
22	export const TRACK_KEYS = TRACKS.map((t) => t.key);
23	export const label = (k: TrackKey) => TRACKS.find((t) => t.key === k)!.label;
24	
25	export const RECOMMEND = '잘 모르겠어요, 추천해 줘';
26	export const MAX_QUESTIONS = 8; // stop rule
27	export const HARD_CAP = 12; // "질문 하나 더" can go past MAX_QUESTIONS up to this
28	export const THRESHOLD = 0.2; // ouroboros AMBIGUITY_THRESHOLD
29	export const CLEAR = 0.3; // ledger shows 명확 at or below this
30	
31	// Words in the prompt or an answer that already say something about a track.
32	const SIGNALS: Record<TrackKey, RegExp> = {
33	  fun: /퍼즐|rpg|액션|농장|키우|리듬|슈팅|시뮬|카드|로그라이크|방치|타이쿤|추리|격투|레이싱|힐링|운영|대전/i,
34	  role: /되어|되는|주인공|플레이어는|사장|용사|역할|조종/,
35	  loop: /반복|모으|수확|싸우|피하|풀고|만들|키우|탐험/,
36	  win: /이기|지면|살아남|탈출|클리어|목표|점수|랭킹|생존|승리|패배/,
37	  platform: /모바일|폰|스마트폰|pc|컴퓨터|스팀|콘솔|스위치|웹|브라우저|짧게|한 판/i,
38	  mood: /귀여|어두|느긋|픽셀|도트|레트로|무서|따뜻|힐링|잔잔|감성|공포|밝은|파스텔/,
39	  audience: /친구|아이|혼자|같이|커플|가족|동생|초보|누구나/,
40	  unique: /다른|새로운|처음|독특|특이|섞|조합|유일/,
41	};
42	
43	const CHARACTERS = ['고양이', '강아지', '토끼', '공룡', '드래곤', '용', '로봇', '좀비', '유령', '닌자', '해적', '마법사', '기사', '외계인', '펭귄', '햄스터'];
44	const PLACES = ['우주', '바다', '숲', '농장', '학교', '카페', '식당', '도시', '던전', '섬', '사막', '지하철', '편의점', '부엌', '꿈'];
45	
46	export const clamp = (n: number) => Math.min(1, Math.max(0, n));
47	const round = (n: number) => Math.round(n * 100) / 100;
48	
49	/** 을/를, 이/가 … picked by the last syllable's final consonant. */
50	export function josa(word: string, withFinal: string, without: string): string {
51	  const c = word.replace(/[\s'"’”)\].,!?…]+$/, '').slice(-1).charCodeAt(0);
52	  if (c >= 0xac00 && c <= 0xd7a3) return (c - 0xac00) % 28 ? withFinal : without;
53	  return without;
54	}
55	
56	export function themes(prompt: string): { chars: string[]; places: string[] } {
57	  return { chars: CHARACTERS.filter((w) => prompt.includes(w)).slice(0, 1), places: PLACES.filter((w) => prompt.includes(w)).slice(0, 2) };
58	}
59	
60	function subject(prompt: string): string {
61	  const { chars, places } = themes(prompt);
62	  const words = [...chars, ...places].slice(0, 2);
63	  if (!words.length) return '이 게임';
64	  if (words.length === 1) return `${words[0]}${josa(words[0], '이', '가')} 나오는 이 게임`;
65	  return `${words[0]}${josa(words[0], '과', '와')} ${words[1]}${josa(words[1], '이', '가')} 나오는 이 게임`;
66	}
67	
68	export function initialLedger(prompt: string): Ledger {
69	  const l = {} as Ledger;
70	  for (const k of TRACK_KEYS) l[k] = SIGNALS[k].test(prompt) ? 0.55 : 1;
71	  if (themes(prompt).chars.length) l.role = Math.min(l.role, 0.7);
72	  return l;
73	}
74	
75	export function overall(l: Ledger): number {
76	  return round(TRACKS.reduce((s, t) => s + t.weight * clamp(l[t.key] ?? 1), 0));
77	}
78	
79	/** Deterministic re-score after an answer: the answered track drops by how concrete the answer was; words in it lower other tracks a little. */
80	export function applyAnswer(l: Ledger, track: TrackKey, a: Answer): Ledger {
81	  const next = { ...l };
82	  const picked = a.choices.filter((c) => c !== RECOMMEND);
83	  const text = a.text.trim();
84	  let score: number;
85	  if (picked.length && text) score = 0.05;
86	  else if (picked.length) score = 0.15;
87	  else if (text.length >= 6) score = 0.1;
88	  else if (a.choices.includes(RECOMMEND)) score = 0.3;
89	  else score = 0.45; // a very short free answer stays fuzzy
90	  next[track] = Math.min(l[track], score);
91	  const said = [...picked, text].join(' ');
92	  for (const k of TRACK_KEYS) if (k !== track && SIGNALS[k].test(said)) next[k] = Math.min(next[k], 0.5);
93	  return next;
94	}
95	
96	export const blockedTrack = (history: TrackKey[]): TrackKey | null =>
97	  history.length >= 2 && history.at(-1) === history.at(-2) ? history.at(-1)! : null;
98	
99	/** Most ambiguous track; after 2 consecutive turns on one track, zoom out to another (ouroboros breadth control).
100	 *  The first question is the ontological one ("what IS this game?") unless the prompt already pinned the fun down. */
101	export function pickTrack(l: Ledger, history: TrackKey[]): TrackKey {
102	  if (!history.length && l.fun > CLEAR) return 'fun';
103	  const blocked = blockedTrack(history);
104	  let best: TrackKey | null = null;
105	  for (const k of TRACK_KEYS) if (k !== blocked && (best === null || l[k] > l[best])) best = k;
106	  return best!;
107	}
108	
109	export function shouldStop(l: Ledger, asked: number): boolean {
110	  return overall(l) <= THRESHOLD || asked >= MAX_QUESTIONS;
111	}
112	
113	/** One readable decision per answered turn ("추천" picks the first option, which is always the recommended one). */
114	export function decisionOf(t: Turn): string {
115	  if (!t.answer) return '';
116	  const parts = t.answer.choices.map((c) => (c === RECOMMEND ? `${t.options[0] ?? '추천안'}(추천)` : c));
117	  if (t.answer.text.trim()) parts.push(t.answer.text.trim());
118	  return parts.join(', ');
119	}
120	
121	export function decisions(turns: Turn[]): Decision[] {
122	  const out: Decision[] = [];
123	  for (const k of TRACK_KEYS) {
124	    const d = turns.filter((t) => t.track === k && t.answer).map(decisionOf).filter(Boolean);
125	    if (d.length) out.push({ key: k, track: label(k), decision: d.join(', ') });
126	  }
127	  return out;
128	}
129	
130	const short = (s: string, n = 24) => (s.length > n ? `${s.slice(0, n).trim()}…` : s);
131	function said(turns: Turn[], k: TrackKey): string {
132	  const t = turns.find((x) => x.track === k && x.answer);
133	  if (!t) return '';
134	  return short(t.answer!.choices.find((c) => c !== RECOMMEND) ?? (t.answer!.choices.includes(RECOMMEND) ? t.options[0] ?? '' : t.answer!.text.trim()));
135	}
136	
137	type Kind = 'grow' | 'puzzle' | 'action' | 'story' | 'versus' | 'other';
138	const KINDS: [Kind, RegExp][] = [
139	  ['grow', /키우|농장|가꾸|꾸미|운영|카페|가게|타이쿤|방치|수집|모으|힐링|느긋/],
140	  ['puzzle', /퍼즐|머리|푸는|추리|탐정|두뇌|맞추/],
141	  ['action', /액션|싸우|전투|피하|슈팅|달리|점프|빠르|짜릿|리듬/],
142	  ['story', /이야기|스토리|소설|선택지|연애|대화/],
143	  ['versus', /대전|겨루|pvp|배틀|경쟁|대결|멀티/i],
144	];
145	export function kind(text: string): Kind {
146	  return KINDS.find(([, re]) => re.test(text))?.[0] ?? 'other';
147	}
148	const gameKind = (prompt: string, turns: Turn[]) => kind(said(turns, 'fun') || prompt);
149	
150	const LOOPS: Record<Kind, string[]> = {
