""",
"""const short = (s: string, n = 24) => (s.length > n ? `${s.slice(0, n).trim()}…` : s);
/** Everything said on a track: picked options ("추천" resolved to the first option) plus the typed text. */
function picks(turns: Turn[], k: TrackKey): string[] {
  return turns.filter((t) => t.track === k && t.answer)
