    .filter(Boolean).map((s) => short(s));
}
const said = (turns: Turn[], k: TrackKey) => picks(turns, k)[0] ?? '';

type Kind = 'grow' | 'puzzle' | 'action' | 'survive' | 'story' | 'versus' | 'other';
